const M={LN:t=>Math.log(t),ABS:t=>Math.abs(t),FUP:t=>Math.ceil(t),SQRT:t=>Math.sqrt(t),FIX:t=>Math.floor(t),ROUND:t=>Math.round(t),BCD:t=>i(t),BIN:t=>e(t),EXP:t=>Math.pow(Math.E,t),SIN:t=>Math.sin(a(t)),COS:t=>Math.cos(a(t)),TAN:t=>Math.tan(a(t)),ASIN:t=>n(Math.asin(t)),ACOS:t=>n(Math.acos(t)),ATAN:t=>n(Math.atan(t))};function a(t){return t*Math.PI/180}function n(t){return 180/Math.PI*t}function i(t){const o=t.toString().split("").map(r=>parseInt(r,10).toString(2).padStart(4,"0"));return parseInt(o.join(""))}function e(t){return Number(t.toString(2))}export{M as STDLIB};
